mapper.select:
SELECT SERIAL_NUMBER, REGIST_DATE, REGIST_IP, MODIFY_DATE, MODIFY_IP, CANCEL_BIT, CANCEL_REASON, CANCEL_DATE, USE_BIT, UNIT_SERIAL, MAKER_TYPE, BIKE_SERIAL, MAKER_ITEM_CODE, ITEM_NAME, ITEM_EN_NAME, ITEM_NICK_NAME, ITEM_UNIT_SET, REAL_NAME, FILE_NAME, FILE_SIZE, FILE_TYPE, IMG_WIDTH, IMG_HEIGHT, MEMO FROM CM_BIKE_ITEM WHERE CANCEL_BIT = 'N'
AND USE_BIT = #{useBit}
AND UNIT_SERIAL = #{unitSerial}
AND MAKER_TYPE = #{makerType}
AND BIKE_SERIAL = #{bikeSerial}
AND MAKER_ITEM_CODE LIKE CONCAT('%', #{makerItemCode}, '%')
AND ITEM_NICK_NAME LIKE CONCAT('%', #{itemNickName}, '%')
AND ITEM_NAME LIKE CONCAT('%', #{keyword}, '%')
AND ITEM_EN_NAME LIKE CONCAT('%', #{keyword}, '%')
AND ITEM_NAME LIKE CONCAT('%', #{keyword}, '%')
ORDER BY SERIAL_NUMBER DESC
